<?php

namespace Database\Seeders;

use App\Models\Genre;
use App\Models\Media;
use Illuminate\Database\Seeder;

/**
 * Loads the catalogue generated by database/scripts/import-top-series.php
 * (Wikidata + TMDB metadata, posters stored locally). Titles are upserted by
 * slug, so re-running is safe and never duplicates rows.
 */
class SeriesCatalogSeeder extends Seeder
{
    public function run(): void
    {
        $path = database_path('data/top-series.json');

        if (! is_file($path)) {
            $this->command?->warn('top-series.json not found — skipping the imported catalogue.');
            return;
        }

        $payload = json_decode((string) file_get_contents($path), true);
        $items = $payload['items'] ?? [];

        $genreIds = Genre::query()->pluck('id', 'slug');
        $genreSlug = $genreIds->has('drama') ? 'drama' : $genreIds->keys()->first();

        // `media` has a unique index on (external_provider, external_id); the
        // import is de-duplicated by TMDB id so two Wikidata items for the
        // same show can never collide here.
        $imported = [];
        $alreadyImported = Media::query()
            ->where('external_provider', 'wikidata')
            ->pluck('slug', 'external_id');

        foreach ($items as $item) {
            $externalId = (string) $item['external_id'];

            if (isset($alreadyImported[$externalId])) {
                $imported[$item['slug']] = true;
                continue;
            }

            $media = Media::updateOrCreate(
                ['slug' => $item['slug']],
                [
                    'title' => $item['title'],
                    'original_title' => $item['title'],
                    'overview' => $item['overview'],
                    'poster_path' => $item['poster_path'],
                    'media_type' => Media::TYPE_SERIES,
                    'release_year' => $item['release_year'],
                    'language' => 'en',
                    'status' => 'ended',
                    'external_provider' => $item['external_provider'] ?? 'tmdb',
                    'external_id' => $item['external_id'] ?? null,
                ]
            );

            if ($genreSlug) {
                $media->genres()->syncWithoutDetaching([$genreIds[$genreSlug]]);
            }

            $imported[$item['slug']] = true;
        }

        $this->command?->info('Imported series catalogue: '.count($items).' titles.');
    }
}
